import { icon, logo } from './app.js';
import { B, places, culture, stories, timeline, routes, photos, sources, allEntries } from './data.js';

const $ = selector => document.querySelector(selector);
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const normalize = value => String(value).normalize('NFD').replace(/[\u0300-\u036f\u064B-\u065F]/g,'').toLowerCase();
const storage = { get(key,fallback){try{return JSON.parse(localStorage.getItem(key)) ?? fallback;}catch{return fallback;}},set(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{}} };
let lang = storage.get('tetouan-language','fr') === 'ar' ? 'ar' : 'fr';
let saved = new Set(storage.get('tetouan-saved',[]).filter(id => allEntries.some(item => item.id === id)));
let currentRoute = '/', selectedRoute = routes[0].id, currentFilter = 'all', query = '', heroFilter = 'all', returnFocus = null, toastTimer;
let observer, baseDocumentTitle = '';
const text = value => value?.[lang] ?? value?.fr ?? value ?? '';
const L = (fr,ar) => lang === 'ar' ? ar : fr;
const photoFor = id => photos.find(photo => photo.id === id) || photos[0];
const entryFor = id => allEntries.find(entry => entry.id === id);
const labels = {
 all:B('Tout explorer','اكتشف الكل'),medina:B('La médina','المدينة العتيقة'),city:B('La ville','المدينة'),culture:B('Culture','ثقافة'),nature:B('Nature','طبيعة'),coast:B('Côté mer','قرب البحر'),crafts:B('Métiers d’art','الحرف الفنية'),music:B('Musique','موسيقى'),food:B('Gastronomie','مطبخ'),art:B('Création','إبداع'),history:B('Histoire','تاريخ'),heritage:B('Patrimoine','تراث'),football:B('Football','كرة القدم')
};
const typeLabels = {district:B('Quartier & secteur','حي وقطاع'),place:B('À découvrir','للاكتشاف'),culture:B('Art & tradition','فن وتقليد'),story:B('Récit documenté','قصة موثقة')};
const image = (id,cls='',eager=false) => {const p=photoFor(id);return `<img class="${cls}" src="${p.src}" alt="${escape(text(p.title))}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;};
const saveButton = entry => `<button class="save-button ${saved.has(entry.id)?'saved':''}" data-save="${entry.id}" aria-label="${escape(L('Enregistrer','حفظ')+' '+text(entry.title))}" aria-pressed="${saved.has(entry.id)}">${icon('heart')}</button>`;
const card = entry => `<article class="place-card reveal"><div class="card-image"><a class="card-heading-link" href="#/lieu/${entry.id}" aria-label="${escape(text(entry.title))}">${image(entry.photoId)}</a><span class="card-tag">${escape(text(labels[entry.category]))}</span>${saveButton(entry)}</div><div class="card-info"><div class="card-meta"><span>${escape(text(typeLabels[entry.type]))}</span><span lang="${lang==='fr'?'ar':'fr'}">${escape(lang==='fr'?entry.title.ar:entry.title.fr)}</span></div><h3><a href="#/lieu/${entry.id}">${escape(text(entry.title))}</a></h3><p>${escape(text(entry.summary))}</p></div></article>`;
const head = (eyebrow,title,description) => `<div class="page-head"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>`;
const sourceLinks = ids => ids.map(id=>`<a href="${sources[id].url}" target="_blank" rel="noopener noreferrer">${escape(sources[id].name)}</a>`).join('');
const sectionHead = (tag,title,description,link,linkText) => `<div class="section-heading"><div><div class="eyebrow">${tag}</div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${link?`<a class="section-link" href="#${link}">${linkText}${icon('chevron')}</a>`:''}</div>`;

function shell() {
 document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';
 $('#header').innerHTML=`<div class="site-header wrap"><a href="#/" class="brand" aria-label="${L('Tétouan, accueil','تطوان، الرئيسية')}">${logo}</a><nav class="nav" id="main-nav" aria-label="${L('Navigation principale','القائمة الرئيسية')}"><a href="#/" data-route="/">${L('Découvrir','اكتشف')}</a><a href="#/quartiers" data-route="/quartiers">${L('Les quartiers','الأحياء')}</a><a href="#/histoire" data-route="/histoire">${L('Histoire & récits','تاريخ وقصص')}</a><a href="#/culture" data-route="/culture">${L('Culture','ثقافة')}</a><a href="#/football" data-route="/football">${L('Football','كرة القدم')}</a></nav><div class="header-actions"><button class="icon-button search-button" data-search aria-label="${L('Rechercher dans le guide','ابحث في الدليل')}">${icon('search')}</button><button class="lang-button" data-language aria-label="${L('Passer à l’arabe','التحويل إلى الفرنسية')}">${lang.toUpperCase()} ${icon('globe')}</button><a class="button small" href="#/itineraires">${L('Mon escapade','جولتي')}</a><button class="icon-button menu-button" aria-label="${L('Ouvrir le menu','افتح القائمة')}" aria-expanded="false" aria-controls="main-nav" data-menu>${icon('menu')}</button></div></div>`;
 $('#footer').innerHTML=`<div class="wrap"><div class="footer-top"><div class="footer-brand"><a class="brand" href="#/">${logo}</a><p>${L('Un guide indépendant pour découvrir Tétouan avec curiosité et respect.','دليل مستقل لاكتشاف تطوان بفضول واحترام.')}</p><button class="text-button" data-search>${icon('search')}${L('Chercher dans le guide','ابحث في الدليل')}</button></div><div class="footer-group"><h3>${L('Explorer','اكتشف')}</h3><a href="#/quartiers">${L('Les quartiers','الأحياء')}</a><a href="#/lieux">${L('Les lieux à découvrir','معالم للاكتشاف')}</a><a href="#/culture">${L('Arts & traditions','فنون وتقاليد')}</a><a href="#/recits">${L('Les récits de la ville','قصص المدينة')}</a><a href="#/football">${L('Le football','كرة القدم')}</a></div><div class="footer-group"><h3>${L('Préparer sa visite','خطط لزيارتك')}</h3><a href="#/itineraires">${L('Les itinéraires','الجولات')}</a><a href="#/favoris">${L('Mes lieux enregistrés','أماكني المحفوظة')} (${saved.size})</a><a href="#/galerie">${L('Regards sur la ville','صور المدينة')}</a><a href="#/sources">${L('Sources & photographies','المصادر والصور')}</a></div></div><div class="footer-bottom"><span>© 2026 ${L('Tétouan — La ville qui se raconte','تطوان — مدينة تحكي قصصها')}</span><span>${L('Contenu vérifié le 8 octobre 2026','محتوى تمت مراجعته في 8 أكتوبر 2026')} · <a href="#/sources">${L('Nos références','مراجعنا')}</a></span></div></div>`;
 const active=currentRoute==='/recits'?'/histoire':currentRoute==='/lieux'?'/quartiers':currentRoute;
 $('#header').querySelectorAll('[data-route]').forEach(link=>{if(link.dataset.route===active){link.classList.add('active');link.setAttribute('aria-current','page');}});
}

function home() {
 const p=photoFor('hero');
 return `<div class="hero-shell">${image('hero','hero-image',true)}<div class="hero-shade"></div><div class="hero-inner wrap"><div class="hero-top"><span class="dot"></span>${L('NORD DU MAROC · ENTRE RIF ET MÉDITERRANÉE','شمال المغرب · بين الريف والبحر المتوسط')}</div><h1 class="hero-title">${L('Une ville.<br>Mille histoires.<br><em>Tétouan.</em>','مدينة واحدة.<br>ألف حكاية.<br><em>تطوان.</em>')}</h1><p class="hero-description">${L('Des ruelles blanches aux souvenirs d’Andalousie,<br>laissez la Colombe blanche vous raconter son monde.','من الأزقة البيضاء إلى ذكريات الأندلس،<br>دع الحمامة البيضاء تحكي لك عالمها.')}</p><div class="hero-buttons"><a class="button lime" href="#/quartiers">${icon('map')}${L('Explorer les quartiers','اكتشف الأحياء')}</a><a class="text-button" href="#/histoire"><span class="play-icon">${icon('play')}</span>${L('L’histoire de la ville','تاريخ المدينة')}</a></div><div class="hero-coordinates">35°34′ N · 5°22′ O</div><div class="hero-bottom"><a class="heritage-badge" href="${sources.unesco.url}" target="_blank" rel="noopener noreferrer">${icon('building')}<span><strong>${L('Un héritage universel','تراث عالمي')}</strong>${L('Médina inscrite à l’UNESCO depuis 1997','المدينة العتيقة مصنفة لدى اليونسكو منذ 1997')}</span></a><a href="#explore" data-scroll="explore" class="scroll-hint">${L('Prenez le temps de découvrir','تمهل واكتشف')}<span class="scroll-line"></span></a><p class="hero-caption">${L('La médina, au pied du Rif','المدينة العتيقة عند سفوح الريف')}<br>${p.author} · ${p.license}</p></div></div></div>
 <div class="intro-strip wrap reveal"><h2>${L('Il y a des villes que l’on visite.<br>Et celles que l’on <em>ressent.</em> <span class="arabic-word" lang="ar">تطوان</span>','هناك مدن نزورها.<br>ومدن <em>نحس بها.</em> تطوان')}</h2><p>${L('Au pied du Rif, Tétouan se découvre à hauteur de rue. Une porte sculptée, un atelier ouvert, un café sur une place : chaque détour révèle une autre facette de la ville.','عند سفوح الريف تكتشف تطوان على مهل. باب منقوش، ورشة مفتوحة، مقهى في ساحة: كل منعطف يكشف وجهاً آخر للمدينة.')}</p></div>
 <section id="explore" class="section wrap">${sectionHead(L('Une ville, plusieurs mondes','مدينة، عوالم متعددة'),L('À chaque quartier, son histoire.','لكل حي حكايته.'),L('Choisissez une ambiance. Laissez les rues faire le reste.','اختر الأجواء ودع الأزقة تكمل الحكاية.'),'/quartiers',L('Tous les quartiers','جميع الأحياء'))}<div class="category-tabs" aria-label="${L('Ambiances à explorer','أجواء للاكتشاف')}">${['all','medina','city','culture','coast'].map(key=>`<button class="chip ${heroFilter===key?'active':''}" data-home-filter="${key}" aria-pressed="${heroFilter===key}">${text(labels[key])}</button>`).join('')}</div><div class="cards" id="home-cards">${homeCards()}</div></section>
 <section class="section wrap"><div class="discovery-row"><div class="feature-image reveal">${image('medina')}<span class="image-note">${L('Médina de Tétouan · patrimoine mondial','المدينة العتيقة لتطوان · تراث عالمي')}</span></div><div class="feature-copy reveal"><div class="eyebrow">${L('L’âme de Tétouan','روح تطوان')}</div><h2>${L('Une médina vivante.<br>Un héritage à partager.','مدينة عتيقة حية.<br>وتراث نكتشفه معاً.')}</h2><p>${L('L’Andalousie a laissé son empreinte dans les maisons et les arts de Tétouan. Mais la médina est aussi un lieu habité : on la découvre en respectant les seuils, les ateliers et le rythme de ses rues.','تركت الأندلس أثرها في بيوت تطوان وفنونها. والمدينة العتيقة أيضاً مكان يعيش فيه الناس؛ نكتشفها باحترام عتبات المنازل والورشات وإيقاع الأزقة.')}</p><div class="facts"><div class="fact"><strong>1997</strong><span>${L('Inscription de la médina<br>au patrimoine mondial','تصنيف المدينة العتيقة<br>ضمن التراث العالمي')}</span></div><div class="fact"><strong>7</strong><span>${L('Portes historiques<br>pour entrer dans la ville','أبواب تاريخية<br>للدخول إلى المدينة')}</span></div><div class="fact"><strong>2017</strong><span>${L('Ville créative<br>des métiers d’art','مدينة مبدعة<br>في الحرف الفنية')}</span></div></div><a class="button" href="#/lieux">${icon('building')}${L('Découvrir le patrimoine','اكتشف التراث')}</a><p class="source-caption">${L('Références :','المراجع:')} <a href="${sources.unesco.url}" target="_blank" rel="noopener noreferrer">UNESCO</a> · <a href="${sources.creative.url}" target="_blank" rel="noopener noreferrer">${L('Villes créatives','المدن المبدعة')}</a></p></div></div></section>
 <section class="section dark-section"><div class="wrap">${sectionHead(L('La mémoire, au présent','الذاكرة في الحاضر'),L('Des histoires qui restent.','حكايات تبقى.'),L('Des personnes, des événements et des lieux. Des récits documentés pour lire la ville autrement.','أشخاص وأحداث وأماكن. قصص موثقة لقراءة المدينة من زاوية أخرى.'),'/recits',L('Tous les récits','جميع القصص'))}<div class="story-grid">${stories.filter(s=>['mandri-story','oddi-story','mat-story'].includes(s.id)).map((s,i)=>`<article class="story-tile ${i===0?'featured':''} reveal"><small>${text(labels[s.category])}</small><span class="story-number">0${i+1}</span><h3>${text(s.title)}</h3><p>${text(s.summary)}</p><a href="#/lieu/${s.id}">${icon('book')}${L('Lire le récit','اقرأ القصة')}</a></article>`).join('')}</div></div></section>
 <section class="section wrap"><div class="route-banner reveal"><div class="route-banner-copy"><div class="eyebrow">${L('Votre prochain détour','جولتك القادمة')}</div><h2>${L('Un matin dans la médina.<br>Le soir, la Méditerranée.','صباح في المدينة العتيقة.<br>ومساء على المتوسط.')}</h2><p>${L('Une demi-journée, un jour ou un week-end : choisissez un parcours et retrouvez vos lieux préférés.','نصف يوم أو يوم أو نهاية أسبوع: اختر جولة وارجع لأماكنك المفضلة.')}</p><a class="button" href="#/itineraires">${icon('map')}${L('Trouver mon itinéraire','اختر جولتي')}</a></div><div class="route-banner-image">${image('martil')}</div></div></section>`;
}
function homeCards(){const ids=heroFilter==='all'?['el-blad','feddan','ensanche']:places.filter(p=>p.category===heroFilter).slice(0,3).map(p=>p.id);return ids.map(id=>card(entryFor(id))).join('');}

function collectionPage(route) {
 const configs={
  '/quartiers':{tag:L('À hauteur de rue','على إيقاع الأزقة'),title:L('Tétouan, quartier par quartier.','تطوان، حياً بحي.'),description:L('Douze quartiers et secteurs pour découvrir ce qui attire les visiteurs : ruelles, places, architecture et vie locale.','اثنا عشر حياً وقطاعاً للتعرف على جاذبيتها: أزقة وساحات وهندسة وحياة محلية.'),items:places.filter(p=>p.type==='district'),filters:['all','medina','city']},
  '/lieux':{tag:L('Les lieux à découvrir','معالم للاكتشاف'),title:L('Suivez votre curiosité.','اتبع فضولك.'),description:L('Des portes de la médina à Martil : des repères pour votre prochaine promenade.','من أبواب المدينة العتيقة إلى مرتيل: محطات لجولتك القادمة.'),items:places,filters:['all','medina','city','culture','nature','coast']},
  '/culture':{tag:L('Arts, gestes & traditions','فنون ومهارات وتقاليد'),title:L('La beauté se transmet.','الجمال ينتقل عبر الأجيال.'),description:L('Artisanat, musique et culture : des savoir-faire qui participent à l’identité tétouanaise.','حرف وموسيقى وثقافة: مهارات تشارك في الهوية التطوانية.'),items:[...culture,...places.filter(p=>['museum','dar-oddi','dar-sanaa'].includes(p.id))],filters:['all','crafts','culture','music','food','art']},
  '/recits':{tag:L('La ville se raconte','المدينة تحكي'),title:L('Vraies histoires. Vraies traces.','قصص حقيقية. آثار حقيقية.'),description:L('Cinq récits documentés. Les références sont accessibles dans chaque fiche ; aucun témoignage ni dialogue n’a été inventé.','خمس قصص موثقة. المراجع متاحة في كل بطاقة؛ لم تبتكر شهادات أو حوارات.'),items:stories,filters:['all','history','heritage','football']},
  '/favoris':{tag:L('Votre carnet de voyage','دفتر رحلتك'),title:L('Les lieux que vous aimez.','أماكن تحبها.'),description:L('Retrouvez les fiches enregistrées avec le cœur. Votre sélection est conservée sur cet appareil.','ارجع إلى البطاقات المحفوظة بزر القلب. تحفظ اختياراتك على هذا الجهاز.'),items:allEntries.filter(p=>saved.has(p.id)),filters:['all','medina','city','culture','history','football','coast']}
 };
 const config=configs[route];
 return `<div class="wrap">${head(config.tag,config.title,config.description)}<div class="category-tabs">${config.filters.map(key=>`<button class="chip ${currentFilter===key?'active':''}" data-filter="${key}" aria-pressed="${currentFilter===key}">${text(labels[key])}</button>`).join('')}</div><div class="page-tools"><label class="search-inline">${icon('search')}<input id="collection-query" type="search" value="${escape(query)}" placeholder="${L('Chercher un nom, une ambiance…','ابحث عن اسم أو أجواء…')}" aria-label="${L('Filtrer les fiches','تصفية البطاقات')}"></label><span class="page-count" id="page-count" aria-live="polite"></span></div><section class="all-grid"><div class="cards" id="collection-cards">${collectionCards(config.items)}</div></section></div>`;
}
function filtered(items){return items.filter(item=>(currentFilter==='all'||item.category===currentFilter)&&normalize(`${item.title.fr} ${item.title.ar} ${item.summary.fr} ${item.summary.ar}`).includes(normalize(query)));}
function collectionCards(items){const shown=filtered(items);return shown.length?shown.map(card).join(''):`<div class="empty"><p>${currentRoute==='/favoris'&&!saved.size?L('Votre carnet est encore vide. Touchez un cœur pour garder un lieu.','دفترك فارغ بعد. اضغط على القلب لحفظ مكان.'):L('Aucun résultat. Essayez un autre nom ou une autre catégorie.','لا توجد نتائج. جرب اسماً أو فئة أخرى.')}</p><a class="text-button" href="#/lieux">${icon('map')}${L('Explorer les lieux','اكتشف المعالم')}</a></div>`;}
function collectionItems(){if(currentRoute==='/quartiers')return places.filter(p=>p.type==='district');if(currentRoute==='/lieux')return places;if(currentRoute==='/culture')return [...culture,...places.filter(p=>['museum','dar-oddi','dar-sanaa'].includes(p.id))];if(currentRoute==='/recits')return stories;return allEntries.filter(p=>saved.has(p.id));}
function updateCollection(){const items=collectionItems();$('#collection-cards').innerHTML=collectionCards(items);$('#page-count').textContent=L(`${filtered(items).length} fiches`,`${filtered(items).length} بطاقة`);observe();}

function historyPage(){return `<div class="wrap">${head(L('Des siècles, des héritages','قرون وتراث'),L('Le temps laisse des traces.','الزمن يترك آثاره.'),L('De Tamuda aux reconnaissances UNESCO : une chronologie pour comprendre les migrations, les conflits et les transformations de Tétouan.','من تمودة إلى اعترافات اليونسكو: خط زمني لفهم الهجرات والصراعات وتحولات تطوان.'))}<div class="timeline-layout"><aside class="timeline-aside">${image('panorama')}<p>${L('La bataille de 1860 concerne directement Tétouan. La guerre du Rif est présentée comme un contexte régional. Les récits individuels complètent cette chronologie.','معركة 1860 مرتبطة مباشرة بتطوان. تقدم حرب الريف كسياق إقليمي. تكمل القصص الفردية هذا الخط الزمني.')}<br><a class="text-button" href="#/recits">${icon('book')}${L('Lire les récits','اقرأ القصص')}</a></p></aside><div class="timeline">${timeline.map(item=>`<article class="timeline-entry reveal"><div class="timeline-year">${lang==='ar'?(item.arYear||item.year):item.year}<span class="timeline-label">${text(item.tag)}</span></div><h2>${text(item.title)}</h2><p>${text(item.body)}</p><a href="${sources[item.source].url}" target="_blank" rel="noopener noreferrer">${L('Lire la référence','اقرأ المرجع')} · ${sources[item.source].name}</a></article>`).join('')}</div></div></div>`;}

function footballPage(){return `<div class="wrap">${head(L('La ville en rouge et blanc','المدينة بالأحمر والأبيض'),L('Un club. Toute une ville.','فريق. مدينة كاملة.'),L('Le Moghreb de Tétouan et les racines du football tétouanais : une autre part de la mémoire locale.','المغرب التطواني وجذور كرة القدم التطوانية: جانب آخر من الذاكرة المحلية.'))}<section class="sport-banner reveal"><div><div class="eyebrow">MOGHREB ATHLÉTIC DE TÉTOUAN</div><h2>${L('Le cœur sportif<br>de la Colombe blanche.','القلب الرياضي<br>للحمامة البيضاء.')}</h2><p>${L('Les souvenirs des titres, l’attachement à la ville et le stade Saniat Rmel font partie du récit du MAT. Découvrez ses repères historiques.','ذكريات الألقاب والارتباط بالمدينة وملعب سانية الرمل جزء من قصة المغرب التطواني. اكتشف معالمه التاريخية.')}</p></div><div class="sport-monogram" aria-label="MAT">MAT</div></section><div class="sport-facts"><article class="sport-fact reveal"><strong>2012</strong><h3>${L('Premier titre marocain','أول لقب مغربي')}</h3><p>${L('Le MAT remporte pour la première fois le championnat national.','فاز المغرب التطواني للمرة الأولى بالدوري الوطني.')}</p></article><article class="sport-fact reveal"><strong>2014</strong><h3>${L('Un deuxième sacre','تتويج ثان')}</h3><p>${L('Un nouveau championnat enrichit le palmarès du club.','دوري جديد يضاف إلى ألقاب النادي.')}</p></article><article class="sport-fact reveal"><strong>2014</strong><h3>${L('Le rendez-vous mondial','الموعد العالمي')}</h3><p>${L('Participation à la Coupe du monde des clubs de la FIFA au Maroc.','مشاركة في كأس العالم للأندية المقامة بالمغرب.')}</p></article></div><div class="split-panel"><div><h2>${L('Deux noms dans la mémoire du football','اسمان في ذاكرة كرة القدم')}</h2><p>${L('Le MAT est le club marocain associé aux sacres de 2012 et 2014. L’Atlético Tetuán est un club historique du temps du protectorat, qui a disputé la première division espagnole en 1951–1952. Leurs histoires se croisent dans la mémoire de la ville ; les noms ne doivent pas être confondus.','المغرب التطواني هو الفريق المغربي المرتبط بلقبي 2012 و2014. أتلتيكو تطوان فريق تاريخي من زمن الحماية، لعب الدرجة الأولى الإسبانية في 1951–1952. تتقاطع قصتاهما في ذاكرة المدينة، لكن الاسمين مختلفان.')}</p><div class="detail-source">${sourceLinks(['mat','fifa','atletico'])}</div><h2 style="margin-top:32px">${L('Pour assister à un match','لحضور مباراة')}</h2><p>${L('Consultez les annonces officielles du club pour le calendrier, le stade utilisé et la billetterie. Cette page présente l’histoire du football ; elle n’affiche pas de résultats ni de classement en direct.','راجع إعلانات النادي الرسمية للبرنامج والملعب والتذاكر. هذه الصفحة تقدم التاريخ، ولا تعرض نتائج أو ترتيباً مباشراً.')}</p></div><div>${card(entryFor('saniat-rmel'))}</div></div></div>`;}

function routesPage(){const route=routes.find(r=>r.id===selectedRoute)||routes[0];return `<div class="wrap">${head(L('Prendre le temps','خذ وقتك'),L('Votre Tétouan, à votre rythme.','تطوان على إيقاعك.'),L('Trois suggestions pour relier les lieux. Choisissez le temps dont vous disposez, puis adaptez le parcours à vos envies.','ثلاثة اقتراحات لربط الأماكن. اختر الوقت المتاح وعدل الجولة حسب رغبتك.'))}<div class="route-cards">${routes.map(r=>`<article class="route-card ${r.id===route.id?'selected':''}"><div class="eyebrow">${text(r.category)}</div><h2>${text(r.title)}</h2><p>${text(r.summary)}</p><button class="button ${r.id===route.id?'':'outline'} small" data-itinerary="${r.id}" aria-pressed="${r.id===route.id}">${icon('clock')}${text(r.duration)}</button></article>`).join('')}</div><section class="route-steps" aria-label="${L('Étapes du parcours','مراحل الجولة')}"><div>${route.stops.map((id,i)=>{const s=entryFor(id);return `<article class="route-step"><span class="step-index">${String(i+1).padStart(2,'0')}</span><div><h3>${text(s.title)}</h3><p>${text(s.summary)}</p><a class="text-button" href="#/lieu/${id}">${L('Voir la fiche','شاهد البطاقة')}</a></div></article>`;}).join('')}</div><aside class="route-side"><h2>${text(route.title)}</h2><p>${text(route.tip)}</p><div class="route-summary"><span>${route.stops.length} ${L('étapes suggérées','محطات مقترحة')}</span><span>${text(route.duration)}</span></div><button class="button" data-download-route>${icon('download')}${L('Télécharger le parcours','نزّل الجولة')}</button><button class="text-button" data-save-route>${icon('heart')}${L('Enregistrer les étapes','احفظ المحطات')}</button><p class="source-caption">${L('Le téléchargement crée un carnet texte à conserver sur votre téléphone.','التنزيل ينتج دفتراً نصياً لحفظه في هاتفك.')}</p></aside></section><div class="split-panel"><div><h2>${L('Une visite qui respecte la ville','زيارة تحترم المدينة')}</h2><p>${L('Restez dans les voies publiques, demandez l’accord avant les portraits et respectez les lieux de culte. La médina est un quartier habité.','التزم بالأزقة العمومية واستأذن قبل تصوير الأشخاص واحترم أماكن العبادة. المدينة العتيقة مكان يسكنه الناس.')}</p></div><div><h2>${L('Avant de partir','قبل الانطلاق')}</h2><p>${L('Confirmez les horaires des musées, les possibilités d’accès et les transports. Les parcours indiquent un ordre de visite suggéré ; ils ne remplacent pas un plan ou un guide local.','تأكد من أوقات المتاحف وإمكانية الدخول والنقل. الجولات تقدم ترتيباً مقترحاً للزيارة ولا تعوض خريطة أو مرشداً محلياً.')}</p><a class="text-button" href="${sources.museum.url}" target="_blank" rel="noopener noreferrer">${L('Informations du musée Bab el Oqla','معلومات متحف باب العقلة')}</a></div></div></div>`;}

function galleryPage(){return `<div class="wrap">${head(L('Regards sur la ville','صور المدينة'),L('La lumière de Tétouan.','ضوء تطوان.'),L('Douze photographies réelles, de la médina à la côte. Chaque image conserve son auteur, sa source et sa licence.','اثنتا عشرة صورة حقيقية، من المدينة العتيقة إلى الساحل. لكل صورة اسم مصورها ومصدرها ورخصتها.'))}<section class="gallery-grid">${photos.map(p=>`<button class="gallery-item" data-photo="${p.id}" aria-label="${escape(L('Agrandir : ','تكبير: ')+text(p.title))}">${image(p.id)}<span class="gallery-caption">${text(p.title)}<small>${p.author} · ${p.license}</small></span></button>`).join('')}</section></div>`;}

function sourcesPage(){return `<div class="wrap">${head(L('Pour aller plus loin','للمزيد'),L('Les sources de notre regard.','مصادر نظرتنا.'),L('Un guide indépendant, sans affiliation institutionnelle. Les faits sont reliés à leurs références, les promenades sont des suggestions éditoriales.','دليل مستقل غير تابع لمؤسسة. ترتبط الحقائق بمراجعها والجولات اقتراحات تحريرية.'))}<div class="source-grid">${Object.values(sources).map(s=>`<article class="source-item"><h2>${escape(s.name)}</h2><p>${text(s.description)}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">${L('Consulter la source','اطلع على المصدر')}</a></article>`).join('')}</div><h2 style="font-size:36px;margin-bottom:20px">${L('Les photographies & leurs auteurs','الصور ومصوروها')}</h2><p style="color:var(--muted);font-size:15px">${L('Images de Wikimedia Commons. Elles ont été redimensionnées et compressées ; leur cadrage peut varier dans les cartes. Les vues générales de la médina illustrent parfois un quartier ou un récit sans montrer son lieu exact : leur légende décrit toujours la photographie réelle.','صور من ويكيميديا كومنز. تم تصغيرها وضغطها وقد يختلف إطارها في البطاقات. أحياناً توضح صور عامة للمدينة العتيقة حياً أو قصة دون تصوير مكانها بدقة؛ التعليق يصف دائماً الصورة الحقيقية.')}</p><div class="credits-list">${photos.map(p=>`<article class="credit-row">${image(p.id)}<div><h3 style="font-size:16px;margin-bottom:7px">${text(p.title)}</h3><p>${p.author} · <a href="${p.licenseUrl}" target="_blank" rel="noopener noreferrer">${p.license}</a> · <a href="${p.source}" target="_blank" rel="noopener noreferrer">${L('Fichier original','الملف الأصلي')}</a></p></div></article>`).join('')}</div></div>`;}

function render(route,reset=true) {
 $('#detail-dialog').close();$('#search-dialog').close();
 if(reset){currentFilter='all';query='';}
 currentRoute=route;shell();
 const titleMap={'/':L('La ville qui se raconte','مدينة تحكي قصصها'),'/quartiers':L('Les quartiers','الأحياء'),'/lieux':L('Les lieux','المعالم'),'/histoire':L('Histoire','التاريخ'),'/recits':L('Récits','القصص'),'/culture':L('Culture','الثقافة'),'/football':L('Football','كرة القدم'),'/itineraires':L('Itinéraires','الجولات'),'/galerie':L('Photographies','الصور'),'/sources':L('Sources','المصادر'),'/favoris':L('Mes lieux','أماكني')};
 const templates={'/':home,'/histoire':historyPage,'/football':footballPage,'/itineraires':routesPage,'/galerie':galleryPage,'/sources':sourcesPage};
 $('#content').innerHTML=templates[route]?templates[route]():['/quartiers','/lieux','/culture','/recits','/favoris'].includes(route)?collectionPage(route):`<div class="wrap section">${head('404',L('Cette ruelle nous échappe.','هذا الزقاق غير موجود.'),L('Retrouvez le guide depuis la page d’accueil.','ارجع إلى الدليل من الصفحة الرئيسية.'))}<a class="button" href="#/">${L('Retour à Tétouan','العودة إلى تطوان')}</a></div>`;
 baseDocumentTitle=`${titleMap[route]||'404'} · Tétouan`;document.title=baseDocumentTitle;
 const active=route==='/recits'?'/histoire':route==='/lieux'?'/quartiers':route;
 $('#header').querySelectorAll('[data-route]').forEach(link=>{const on=link.dataset.route===active;link.classList.toggle('active',on);if(on)link.setAttribute('aria-current','page');});
 if($('#page-count'))$('#page-count').textContent=L(`${filtered(collectionItems()).length} fiches`,`${filtered(collectionItems()).length} بطاقة`);
 $('#content').classList.remove('route-enter');void $('#content').offsetWidth;$('#content').classList.add('route-enter');observe();
 document.body.dataset.route=route;
}
function observe(){observer?.disconnect();observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
function route(){let hash;try{hash=decodeURIComponent(location.hash.slice(1)||'/');}catch{render('/404');return;}if(hash.startsWith('/lieu/')){const entry=entryFor(hash.slice(6));if(!entry){render('/404');return;}if(!$('#content').children.length)render('/lieux');showEntry(entry);return;}if(hash==='explore'){if(currentRoute!=='/')render('/');$('#explore')?.scrollIntoView({behavior:'smooth'});return;}render(hash);window.scrollTo({top:0,behavior:'instant'});}

function showEntry(entry) {
 returnFocus=document.activeElement;
 const p=photoFor(entry.photoId), dialog=$('#detail-dialog');
 dialog.innerHTML=`<button class="icon-button dialog-close" data-close aria-label="${L('Fermer la fiche','أغلق البطاقة')}">${icon('close')}</button><div class="detail-photo">${image(entry.photoId,'',true)}</div><div class="detail-credit">${escape(text(p.title))} · ${p.author} · <a href="${p.licenseUrl}" target="_blank" rel="noopener noreferrer">${p.license}</a></div><div class="detail-body"><div class="eyebrow">${text(typeLabels[entry.type])}</div><h2 id="detail-title">${text(entry.title)}</h2><p>${text(entry.body)}</p><h3>${entry.type==='story'?L('À retenir','للتذكر'):L('Ce qui donne envie de venir','ما يجذب الزوار')}</h3><ul>${entry.attractions.map(a=>`<li>${text(a)}</li>`).join('')}</ul><div class="detail-tips"><p>${text(entry.tips)}</p></div><div class="detail-actions"><button class="button ${saved.has(entry.id)?'lime':'outline'}" data-save-detail="${entry.id}">${icon('heart')}${saved.has(entry.id)?L('Enregistré dans mon carnet','محفوظ في دفتري'):L('Enregistrer dans mon carnet','احفظ في دفتري')}</button>${entry.type!=='story'&&entry.type!=='culture'?`<a class="button" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(entry.mapQuery)}" target="_blank" rel="noopener noreferrer">${icon('pin')}${L('Voir sur la carte','شاهد على الخريطة')}</a>`:''}</div><div class="detail-source"><span>${L('Références :','المراجع:')}</span>${sourceLinks(entry.sourceIds)}</div></div>`;
 if(!dialog.open)dialog.showModal();document.title=`${text(entry.title)} · Tétouan`;
}
function showPhoto(id){const p=photoFor(id);returnFocus=document.activeElement;$('#detail-dialog').innerHTML=`<button class="icon-button dialog-close" data-close aria-label="${L('Fermer la photo','أغلق الصورة')}">${icon('close')}</button>${image(p.id,'lightbox-image',true)}<div class="detail-body"><h2 id="detail-title">${text(p.title)}</h2><p>${p.author} · <a href="${p.licenseUrl}" target="_blank" rel="noopener noreferrer">${p.license}</a></p><a class="text-button" href="${p.source}" target="_blank" rel="noopener noreferrer">${L('Voir la source et le fichier original','شاهد المصدر والملف الأصلي')}</a></div>`;$('#detail-dialog').showModal();}
function closeDetail(){if(location.hash.startsWith('#/lieu/'))history.replaceState(null,'',`#${currentRoute}`);$('#detail-dialog').close();document.title=baseDocumentTitle;}
function showSearch(){returnFocus=document.activeElement;$('#search-dialog').innerHTML=`<div class="search-panel"><button class="icon-button dialog-close" data-close-search aria-label="${L('Fermer la recherche','أغلق البحث')}">${icon('close')}</button><h2 id="search-title">${L('Un lieu, une histoire, une envie…','مكان، قصة، رغبة…')}</h2><label class="search-box">${icon('search')}<input id="global-query" type="search" placeholder="${L('El Blad, broderie, 2012…','البلاد، تطريز، 2012…')}" aria-label="${L('Rechercher dans tout le guide','ابحث في كل الدليل')}"></label><div id="search-results" class="search-results" aria-live="polite">${searchResults('')}</div></div>`;$('#search-dialog').showModal();$('#global-query').focus();}
function searchResults(q){const found=allEntries.filter(e=>normalize(`${e.title.fr} ${e.title.ar} ${e.summary.fr} ${e.summary.ar} ${e.body.fr} ${e.body.ar}`).includes(normalize(q))).slice(0,12);return found.length?found.map(e=>`<a class="search-result" href="#/lieu/${e.id}" data-search-result>${image(e.photoId)}<span><h3>${text(e.title)}</h3><small>${text(typeLabels[e.type])}</small></span></a>`).join(''):`<p class="empty">${L('Aucun résultat. Essayez un autre mot.','لا توجد نتائج. جرب كلمة أخرى.')}</p>`;}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function toggleSave(id){if(saved.has(id))saved.delete(id);else saved.add(id);storage.set('tetouan-saved',[...saved]);document.querySelectorAll(`[data-save="${id}"]`).forEach(btn=>{btn.classList.toggle('saved',saved.has(id));btn.setAttribute('aria-pressed',String(saved.has(id)));});document.querySelectorAll(`[data-save-detail="${id}"]`).forEach(btn=>{btn.classList.toggle('lime',saved.has(id));btn.classList.toggle('outline',!saved.has(id));btn.innerHTML=`${icon('heart')}${saved.has(id)?L('Enregistré dans mon carnet','محفوظ في دفتري'):L('Enregistrer dans mon carnet','احفظ في دفتري')}`;});if(currentRoute==='/favoris')updateCollection();toast(saved.has(id)?L('Ajouté à votre carnet de voyage','أضيف إلى دفتر رحلتك'):L('Retiré de votre carnet','حذف من دفترك'));shell();}
function downloadRoute(){const route=routes.find(r=>r.id===selectedRoute);const content=[text(route.title),'Tétouan — '+L('La ville qui se raconte','مدينة تحكي قصصها'),'',text(route.tip),'',...route.stops.map((id,i)=>`${i+1}. ${text(entryFor(id).title)}\n${text(entryFor(id).summary)}\nhttps://www.google.com/maps/search/?api=1&query=${encodeURIComponent(entryFor(id).mapQuery)}`),'',L('Les horaires, les accès et les transports sont à vérifier sur place.','تأكد من الأوقات وإمكانية الدخول والنقل في المكان.')].join('\n\n');const url=URL.createObjectURL(new Blob(['\uFEFF',content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`tetouan-${route.id}-${lang}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(L('Votre carnet est prêt à télécharger','دفترك جاهز للتنزيل'));}

document.addEventListener('click',event=>{
 const target=event.target.closest('button,a');if(!target)return;
 if(target.hasAttribute('data-language')){lang=lang==='fr'?'ar':'fr';storage.set('tetouan-language',lang);const detailId=location.hash.startsWith('#/lieu/')?location.hash.slice(7):null;render(currentRoute,false);if(detailId&&entryFor(detailId))showEntry(entryFor(detailId));}
 if(target.hasAttribute('data-menu')){const open=$('.nav').classList.toggle('open');target.setAttribute('aria-expanded',String(open));}
 if(target.hasAttribute('data-search'))showSearch();
 if(target.hasAttribute('data-close'))closeDetail();
 if(target.hasAttribute('data-close-search'))$('#search-dialog').close();
 if(target.hasAttribute('data-search-result'))$('#search-dialog').close();
 if(target.dataset.save)toggleSave(target.dataset.save);
 if(target.dataset.saveDetail)toggleSave(target.dataset.saveDetail);
 if(target.dataset.filter){currentFilter=target.dataset.filter;document.querySelectorAll('[data-filter]').forEach(btn=>{btn.classList.toggle('active',btn.dataset.filter===currentFilter);btn.setAttribute('aria-pressed',String(btn.dataset.filter===currentFilter));});updateCollection();}
 if(target.dataset.homeFilter){heroFilter=target.dataset.homeFilter;document.querySelectorAll('[data-home-filter]').forEach(btn=>{btn.classList.toggle('active',btn.dataset.homeFilter===heroFilter);btn.setAttribute('aria-pressed',String(btn.dataset.homeFilter===heroFilter));});$('#home-cards').innerHTML=homeCards();observe();}
 if(target.dataset.itinerary){selectedRoute=target.dataset.itinerary;$('#content').innerHTML=routesPage();observe();}
 if(target.dataset.photo)showPhoto(target.dataset.photo);
 if(target.hasAttribute('data-download-route'))downloadRoute();
 if(target.hasAttribute('data-save-route')){routes.find(r=>r.id===selectedRoute).stops.forEach(id=>saved.add(id));storage.set('tetouan-saved',[...saved]);shell();toast(L('Toutes les étapes ont rejoint votre carnet','حفظت جميع المحطات في دفترك'));}
 if(target.dataset.scroll){event.preventDefault();document.getElementById(target.dataset.scroll)?.scrollIntoView({behavior:'smooth'});}
});
document.addEventListener('input',event=>{if(event.target.id==='collection-query'){query=event.target.value;updateCollection();}if(event.target.id==='global-query')$('#search-results').innerHTML=searchResults(event.target.value);});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='k'){event.preventDefault();showSearch();}if(event.key==='Escape')$('.nav')?.classList.remove('open');});
for(const id of ['detail-dialog','search-dialog']){const dialog=$('#'+id);dialog.addEventListener('cancel',event=>{if(id==='detail-dialog'){event.preventDefault();closeDetail();}});dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom){if(id==='detail-dialog')closeDetail();else dialog.close();}}});dialog.addEventListener('close',()=>{if(!dialog.open&&returnFocus?.isConnected)returnFocus.focus();});}
let scrollFrame;
window.addEventListener('scroll',()=>{if(currentRoute!=='/'||matchMedia('(prefers-reduced-motion: reduce)').matches||scrollFrame)return;scrollFrame=requestAnimationFrame(()=>{$('.hero-image')?.style.setProperty('--hero-shift',`${Math.min(25,window.scrollY*.045)}px`);scrollFrame=null;});},{passive:true});
window.addEventListener('hashchange',route);
route();
